use super::*;
use crate::pet_runtime::{continuation_tests::{closed,review},admission_tests::{evidence,budget,Fixture},authority_store::Fault as AuthFault,store::{Store,Fault},model,reconciliation_tests::inventory};
use std::{fs::{self,OpenOptions},os::fd::AsRawFd};
fn prepare(env:&crate::pet_runtime::recovery_tests::Environment,goal:&Record)->(Reviews,ReviewTicket,std::sync::Arc<Pending>){
    let mut cache=Reviews::default();let ticket=cache.insert("settings",review(env,goal,"native-continuation",100_030),crate::pet_runtime::store::nonce().unwrap(),100_030).unwrap();let input=ConfirmInput{memory_consent:None,pet_id:goal.spec.owner.pet_id.clone(),goal_id:goal.id.clone(),revision:goal.revision.clone(),token:ticket.token.clone(),approve:true};let pending=cache.lookup("settings",&input,100_031).unwrap();(cache,ticket,pending)
}
fn confirm(p:&Pending,store:&Store,path:&std::path::Path,approve:bool,now:u64)->model::Result<ConfirmResult>{p.confirm(store,path,approve,|goal,now|Ok(Ok((evidence(goal,now),()))),||now)}
fn fault(p:&Pending,value:AuthFault){let mut native=p.native.lock().unwrap();let Native::Approved{authority,..}=&mut*native else{panic!("same original native approval required")};authority.fault=value;}
fn native_spec(p:&Pending)->AdmissionSpec{let n=p.native.lock().unwrap();let Native::Approved{approved,..}=&*n else{panic!("native approval missing")};approved.spec().clone()}
#[test]fn the_retained_source_authority_and_choice_survive_busy_staging_and_both_publications(){
    let(env,g)=closed("ollama","started");let(_cache,_ticket,p)=prepare(&env,&g);let lock=OpenOptions::new().read(true).write(true).open(crate::pet_runtime::authority_tests::root(&env.fixture).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);
    assert!(matches!(confirm(&p,&env.store,&env.fixture.path.join("must-not-create-authority"),true,100_031).unwrap(),ConfirmResult::AuthorityBlocked{reason:crate::pet_runtime::authority::Failure::Busy,retryable:true}));let original=native_spec(&p);drop(lock);assert!(!env.fixture.path.join("must-not-create-authority").exists());
    fault(&p,AuthFault::BeforeGrantPublish);assert!(matches!(confirm(&p,&env.store,&crate::pet_runtime::authority_tests::root(&env.fixture),true,100_032).unwrap(),ConfirmResult::AuthorityBlocked{retryable:true,..}));assert_eq!(model::fingerprint(&native_spec(&p)).unwrap(),model::fingerprint(&original).unwrap());
    fault(&p,AuthFault::None);let mut unavailable=Store::existing_verified(&env.fixture.path.join("goals"),&crate::pet_runtime::authority_tests::root(&env.fixture)).unwrap().unwrap();unavailable.fault=Fault::BeforePublish;assert!(matches!(confirm(&p,&unavailable,&crate::pet_runtime::authority_tests::root(&env.fixture),true,100_033).unwrap(),ConfirmResult::AuthorityBlocked{retryable:true,..}));assert_eq!(env.store.read(&g.id,"ai_ollama").unwrap().revision,g.revision);
    let receipt=match confirm(&p,&env.store,&crate::pet_runtime::authority_tests::root(&env.fixture),true,100_034).unwrap(){ConfirmResult::Queued{receipt}=>receipt,_=>panic!("retained choice must enqueue once")};assert_eq!(receipt.record.admissions.len(),2);assert_eq!(model::fingerprint(&receipt.record.admissions[1].spec).unwrap(),model::fingerprint(&original).unwrap());
    let files=fs::read_dir(crate::pet_runtime::authority_tests::root(&env.fixture)).unwrap().map(|f|f.unwrap().file_name().to_string_lossy().into_owned()).collect::<Vec<_>>();assert!(!files.iter().any(|name|name.starts_with(".grant-")));assert_eq!(original.approved_at,100_031);
    let before=inventory(&env.fixture.path);let ack=p.confirm(&env.store,&env.fixture.path.join("not-an-authority"),true,|_,_|->model::Result<std::result::Result<(Evidence,()),Denial>>{panic!("ACK must not refresh metadata or consent")},||400_000).unwrap();assert!(matches!(ack,ConfirmResult::Queued{..}));assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn uncertain_admission_keeps_its_cache_slot_after_expiry_and_only_acknowledges_the_same_event(){
    let(env,g)=closed("ollama","started");let(mut cache,ticket,p)=prepare(&env,&g);let mut uncertain=Store::existing_verified(&env.fixture.path.join("goals"),&crate::pet_runtime::authority_tests::root(&env.fixture)).unwrap().unwrap();uncertain.fault=Fault::AfterPublish;
    let first=confirm(&p,&uncertain,&crate::pet_runtime::authority_tests::root(&env.fixture),true,100_031).unwrap();assert!(matches!(first,ConfirmResult::Queued{receipt:model::Receipt{status:model::CommitStatus::Uncertain,..}}));let original=native_spec(&p);
    let other=Fixture::new();let draft=other.goal("codex");let mut bounds=budget();bounds.deadline_at=600_000;let review=Review::prepare(&draft,evidence(&draft,400_000),bounds,"other-review".into(),crate::pet_runtime::store::nonce().unwrap(),400_000).unwrap();cache.insert("settings",review,crate::pet_runtime::store::nonce().unwrap(),400_000).unwrap();
    let input=ConfirmInput{memory_consent:None,pet_id:"ai_ollama".into(),goal_id:g.id.clone(),revision:g.revision.clone(),token:ticket.token,approve:true};assert!(cache.lookup("settings",&input,400_001).is_ok());assert!(cache.lookup("mochi",&input,400_001).is_err());
    let result=p.confirm(&env.store,&crate::pet_runtime::authority_tests::root(&env.fixture),true,|_,_|->model::Result<std::result::Result<(Evidence,()),Denial>>{panic!("expired ACK cannot observe or renew authorization")},||400_001).unwrap();let receipt=match result{ConfirmResult::Queued{receipt}=>receipt,_=>panic!("same event ACK required")};assert_eq!(receipt.record.admissions.len(),2);assert_eq!(model::fingerprint(&receipt.record.admissions[1].spec).unwrap(),model::fingerprint(&original).unwrap());
    assert!(crate::pet_runtime::authority::Authority::existing(&crate::pet_runtime::authority_tests::root(&env.fixture)).unwrap().verify_queued(&receipt.record,400_001).is_err());
}
#[test]fn decline_of_the_own_unpublished_candidate_keeps_zero_io_auditable_and_allows_a_fresh_review(){
    let(env,g)=closed("ollama","started");let(_cache,_ticket,p)=prepare(&env,&g);let mut unavailable=Store::existing_verified(&env.fixture.path.join("goals"),&crate::pet_runtime::authority_tests::root(&env.fixture)).unwrap().unwrap();unavailable.fault=Fault::BeforePublish;assert!(matches!(confirm(&p,&unavailable,&crate::pet_runtime::authority_tests::root(&env.fixture),true,100_031).unwrap(),ConfirmResult::AuthorityBlocked{retryable:true,..}));let old_spec=native_spec(&p);assert!(matches!(confirm(&p,&env.store,&crate::pet_runtime::authority_tests::root(&env.fixture),false,100_032).unwrap(),ConfirmResult::Declined));
    assert_eq!(env.store.read(&g.id,"ai_ollama").unwrap().revision,g.revision);let history=env.store.history(&crate::pet_runtime::authority_tests::root(&env.fixture),&g.id,"ai_ollama",&g.revision,100_033).unwrap();assert!(history.accounting_complete);assert_eq!(history.unlinked_grants.len(),1);assert!(history.unlinked_grants[0].revoked_without_io);assert_eq!(history.unlinked_grants[0].decision_id,old_spec.decision_id);
    let next=review(&env,&g,"fresh-after-decline",100_034);let next=next.proposal();assert_eq!(next.continuation.as_ref().unwrap().unused.len(),1);assert_eq!(next.continuation.as_ref().unwrap().charge.model_calls,1);
}

#[test]fn an_unapproved_expired_continuation_does_not_prevent_a_fresh_explicit_review(){
    let(env,g)=closed("ollama","started");let(mut cache,ticket,_p)=prepare(&env,&g);let input=ContinuationPrepareInput{review_uncertain_effects:false,pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),revision:g.revision.clone(),request_id:"changed-ui-fields".into(),budget:budget(),limits:None};let before=inventory(&env.fixture.path);
    assert_eq!(cache.retained_continuation("settings",&input,&g,100_031).unwrap().unwrap().token,ticket.token);
    assert!(cache.retained_continuation("settings",&input,&g,400_000).unwrap().is_none());assert!(cache.retained_continuation("mochi",&input,&g,100_031).unwrap().is_none());assert_eq!(inventory(&env.fixture.path),before);
    let next=cache.insert("settings",review(&env,&g,"fresh-explicit-review",400_000),crate::pet_runtime::store::nonce().unwrap(),400_000).unwrap();assert_ne!(next.token,ticket.token);assert_eq!(next.proposal.continuation.unwrap().charge.model_calls,1);
}
